using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Unity.Collections;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 [InitializeOnLoad] public static class TerrainTestMountainColors {
  const string PathName="Assets/Scenes/AlpsTerrainTest.unity",Folder="Assets/Snowglow/Levels/AlpsTerrainTest/SlopeSnow/",Log="Logs/AlpsMountainColors/";
  class Kept {public string name;public Vector3 at,scale;public Quaternion rotation;public Mesh mesh;}
  static TerrainTestMountainColors(){EditorApplication.update+=Pending;}
  static void Check(bool ok,string why){if(!ok)throw new InvalidOperationException("Slope mountain colors: "+why);}
  static void Pending(){const string marker="Logs/AlpsMountainColors.request";if(!File.Exists(marker)||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)return;string action=File.ReadAllText(marker).Trim();File.Delete(marker);Directory.CreateDirectory(Log);try{if(action=="height")HeightCoverage();else Apply();}catch(Exception e){File.WriteAllText(Log+"Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static Bounds Bounds(GameObject g){var r=g.GetComponentsInChildren<MeshRenderer>();var b=r[0].bounds;foreach(var v in r.Skip(1))b.Encapsulate(v.bounds);return b;}
  static void Apply(){var scene=SceneManager.GetActiveScene();Check(scene.path==PathName,"current test scene only");var group=scene.GetRootGameObjects().Single(g=>g.name=="Mountains | provisional placement");var mountains=group.transform.Cast<Transform>().ToArray();Check(mountains.Length==8&&mountains.All(t=>t.GetComponent<CatalogPlacement>().assetId.StartsWith("alps-mountains-v2-")),"eight supplied V2 mountains");Check(!File.Exists(Folder+"MountainSlopeSnow.mat"),"already installed; adjust saved material properties directly");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss"),backup=Log+"InMemory-before-"+stamp+".unity";Check(EditorSceneManager.SaveScene(scene,backup,true),"preserve unsaved user scene");File.Copy(PathName,Log+"Disk-before-"+stamp+".unity");var kept=mountains.Select(t=>new Kept{name=t.name,at=t.position,scale=t.localScale,rotation=t.rotation,mesh=t.GetComponentInChildren<MeshFilter>().sharedMesh}).ToArray();try{
   var shader=Shader.Find("Snowglow/Alpine Rock and Slope Snow");Check(shader&&!ShaderUtil.ShaderHasError(shader),"compiled URP slope shader");Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var material=new Material(shader){name="Mountains | light gray rock and slope snow",enableInstancing=true};material.SetColor("_SnowColor",new Color(.98f,.99f,1));material.SetColor("_SnowShade",new Color(.83f,.89f,.94f));material.SetColor("_RockLight",new Color(.76f,.78f,.80f));material.SetColor("_RockShade",new Color(.57f,.60f,.63f));material.SetFloat("_SnowMaxSlope",50);material.SetFloat("_SlopeBlend",4);AssetDatabase.CreateAsset(material,Folder+"MountainSlopeSnow.mat");var report=new List<string>();int totalRock=0,totalSnow=0,totalBlend=0;
   foreach(var t in mountains){foreach(var r in t.GetComponentsInChildren<MeshRenderer>())r.sharedMaterial=material;var f=t.GetComponentInChildren<MeshFilter>();using(var data=MeshUtility.AcquireReadOnlyMeshData(f.sharedMesh)){var m=data[0];using(var normals=new NativeArray<Vector3>(m.vertexCount,Allocator.Temp))using(var indices=new NativeArray<int>(m.GetSubMesh(0).indexCount,Allocator.Temp)){m.GetNormals(normals);m.GetIndices(indices,0);var normalMatrix=f.transform.localToWorldMatrix.inverse.transpose;int rock=0,snow=0,blend=0;for(int i=0;i<indices.Length;i+=3){var n=(normalMatrix.MultiplyVector(normals[indices[i]])+normalMatrix.MultiplyVector(normals[indices[i+1]])+normalMatrix.MultiplyVector(normals[indices[i+2]])).normalized;float angle=Vector3.Angle(Vector3.up,n);if(angle>=54)rock++;else if(angle<=46)snow++;else blend++;}Check(rock>0&&snow>0,"visible rock/snow angle classes "+t.name);totalRock+=rock;totalSnow+=snow;totalBlend+=blend;report.Add(t.name+" | rock>=54deg="+rock+" | snow<=46deg="+snow+" | blend="+blend);}}
   }
   AssetDatabase.SaveAssets();Check(EditorSceneManager.SaveScene(scene,PathName),"save mountain shading");scene=EditorSceneManager.OpenScene(PathName);group=scene.GetRootGameObjects().Single(g=>g.name=="Mountains | provisional placement");foreach(var p in kept){var t=group.transform.Cast<Transform>().Single(v=>v.name==p.name);Check(t.position==p.at&&t.rotation==p.rotation&&t.localScale==p.scale,"placement retained "+p.name);var f=t.GetComponentInChildren<MeshFilter>();Check(f.sharedMesh==p.mesh&&t.GetComponentInChildren<MeshCollider>().sharedMesh==p.mesh,"original rendering/collision mesh retained");Check(t.GetComponentInChildren<MeshRenderer>().sharedMaterial==material,"saved slope material");}Check(!ShaderUtil.ShaderHasError(shader),"native shader compile after save");Capture(scene,Log+"Overview.png",new Vector3(1150,850,0),Vector3.zero);int k=0;foreach(Transform t in group.transform){var b=Bounds(t.gameObject);Capture(scene,Log+"Mountain"+(++k).ToString("D2")+".png",b.center+new Vector3(1,.5f,-1).normalized*Mathf.Max(b.size.x,b.size.z)*1.4f,b.center);}EditorSceneManager.OpenScene(PathName);File.WriteAllText(Log+"Validation.txt","PASS: test mountains use one shared opaque URP slope material, light gray rock with bounded pale shadows and white/pale-blue snow. Snow limit50deg from horizontal with4deg transition: <=46deg snow, >=54deg exposed rock. World-space normal classification responds to orientation; imported flat normals retain faceted style. No textures/runtime scripts/new lights. All geometry/UVs/colliders/poses and terrain unchanged. Saved/reopened references, native shader and eight angle-class checks passed. Rock="+totalRock+", snow="+totalSnow+", transition="+totalBlend+" triangles. Overview/eight individual captures generated. No Play/device acceptance.\n"+string.Join("\n",report));
  }catch{if(SceneManager.GetActiveScene().isDirty)EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),Log+"Failed-unsaved-"+stamp+".unity",true);File.Copy(backup,PathName,true);AssetDatabase.ImportAsset(PathName,ImportAssetOptions.ForceUpdate);EditorSceneManager.OpenScene(PathName);throw;}}
  static void HeightCoverage(){const string log="Logs/AlpsMountainHeightSnow/";Directory.CreateDirectory(log);var scene=SceneManager.GetActiveScene();Check(scene.path==PathName,"current test scene");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Check(EditorSceneManager.SaveScene(scene,log+"InMemory-before-"+stamp+".unity",true),"preserve user edits");var material=AssetDatabase.LoadAssetAtPath<Material>(Folder+"MountainSlopeSnow.mat");Check(material&&material.HasProperty("_HighSnowSlope"),"height-aware slope material");Check(!ShaderUtil.ShaderHasError(material.shader),"height slope shader compiled");File.Copy(Folder+"MountainSlopeSnow.mat",log+"Material-before-"+stamp+".mat");material.SetFloat("_HighSnowSlope",78);material.SetFloat("_SnowHeightStart",45);material.SetFloat("_SnowHeightEnd",110);EditorUtility.SetDirty(material);AssetDatabase.SaveAssets();Check(EditorSceneManager.SaveScene(scene,PathName),"save current scene");var group=scene.GetRootGameObjects().Single(g=>g.name=="Mountains | provisional placement");int increased=0,total=0;float oldCover=0,newCover=0;var report=new List<string>();float Mix(float cosine,float limit){float low=Mathf.Cos(Mathf.Min(89,limit+material.GetFloat("_SlopeBlend"))*Mathf.Deg2Rad),high=Mathf.Cos(Mathf.Max(0,limit-material.GetFloat("_SlopeBlend"))*Mathf.Deg2Rad);float t=Mathf.Clamp01((cosine-low)/Mathf.Max(.0001f,high-low));return t*t*(3-2*t);}
   foreach(Transform mountain in group.transform){var f=mountain.GetComponentInChildren<MeshFilter>();using(var data=MeshUtility.AcquireReadOnlyMeshData(f.sharedMesh)){var d=data[0];using(var vertices=new NativeArray<Vector3>(d.vertexCount,Allocator.Temp))using(var normals=new NativeArray<Vector3>(d.vertexCount,Allocator.Temp)){d.GetVertices(vertices);d.GetNormals(normals);var matrix=f.transform.localToWorldMatrix.inverse.transpose;int changed=0;for(int i=0;i<d.vertexCount;i++){var world=f.transform.TransformPoint(vertices[i]);float cosine=matrix.MultiplyVector(normals[i]).normalized.y;float low=Mix(cosine,material.GetFloat("_SnowMaxSlope"));float altitude=Mathf.SmoothStep(0,1,Mathf.InverseLerp(45,110,world.y));float high=Mix(cosine,Mathf.Lerp(material.GetFloat("_SnowMaxSlope"),Mathf.Max(material.GetFloat("_SnowMaxSlope"),78),altitude));Check(high>=low-.0001f,"coverage cannot shrink");if(high>low+.05f)changed++;oldCover+=low;newCover+=high;total++;}increased+=changed;report.Add(mountain.name+" | vertices with more snow="+changed+"/"+d.vertexCount);}}}Check(increased>100&&newCover>oldCover,"additional snow on angled upper faces");Capture(scene,log+"Overview.png",new Vector3(1150,850,0),Vector3.zero);int k=0;foreach(Transform t in group.transform){var b=Bounds(t.gameObject);Capture(scene,log+"Mountain"+(++k).ToString("D2")+".png",b.center+new Vector3(1,.5f,-1).normalized*Mathf.Max(b.size.x,b.size.z)*1.4f,b.center);}scene=EditorSceneManager.OpenScene(PathName);Check(material.GetFloat("_HighSnowSlope")==78&&material.GetFloat("_SnowHeightStart")==45&&material.GetFloat("_SnowHeightEnd")==110,"saved altitude controls");Check(!ShaderUtil.ShaderHasError(material.shader),"final shader compile");File.WriteAllText(log+"Validation.txt","PASS: snow slope allowance increases from saved base50deg toward78deg with world altitude45-110m, retaining4deg slope blend. More snow at"+increased+"/"+total+" mesh vertices; mean snow coverage"+(oldCover/total)+" to"+(newCover/total)+". No vertex loses snow; meshes/colliders/transforms and gray/snow colors unchanged. Material saved; native overview/eight views captured; scene reopened. No Play/device acceptance.\n"+string.Join("\n",report));}
  static void Capture(Scene scene,string path,Vector3 pos,Vector3 target){var source=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>()).Single();var go=new GameObject("Temporary slope material audit");SceneManager.MoveGameObjectToScene(go,scene);var c=go.AddComponent<Camera>();c.CopyFrom(source);c.enabled=false;c.orthographic=false;c.fieldOfView=55;c.aspect=4f/3;c.farClipPlane=3000;c.layerCullDistances=new float[32];c.transform.SetPositionAndRotation(pos,Quaternion.LookRotation(target-pos));var rt=RenderTexture.GetTemporary(1200,900,24);var old=RenderTexture.active;var image=new Texture2D(1200,900,TextureFormat.RGB24,false);try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1200,900),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());}finally{RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(go);}}
 }
}
